:root {
  --color-primary: #2d5016;
  --color-primary-light: #4a7c2c;
  --color-accent: #d4af37;
  --color-accent-on-dark: #f4d9a6;
  --color-dark: #1a1a1a;
  --color-light: #f9f9f9;
  --color-text: #333333;
  --color-text-light: #666666;
  --color-border: #e0e0e0;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Verdana, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: #ffffff;
  line-height: 1.6;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-primary);
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover, a:focus {
  color: var(--color-primary-light);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Header */
.header {
  background-color: var(--color-light);
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  font-variant: small-caps;
  letter-spacing: 0.15em;
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: 0.25rem;
  display: inline-block;
  transition: var(--transition);
}

.logo:hover, .logo:focus {
  color: var(--color-primary-light);
  text-decoration: none;
}

.header nav {
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.header nav a {
  font-weight: 500;
  font-size: 0.95rem;
  color: var(--color-text);
}

.header nav a:hover, .header nav a:focus {
  color: var(--color-primary);
}

/* Footer */
.footer {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) 0 var(--spacing-lg) 0;
  margin-top: var(--spacing-2xl);
}

.footer-content {
  margin-bottom: var(--spacing-lg);
}

.footer p {
  margin-bottom: var(--spacing-sm);
  color: var(--color-accent-on-dark);
}

.footer strong {
  color: var(--color-accent);
}

.copyright {
  text-align: center;
  padding-top: var(--spacing-md);
  border-top: 1px solid rgba(244, 217, 166, 0.3);
  font-size: 0.85rem;
}

/* Buttons */
button, .btn {
  display: inline-block;
  background-color: var(--color-primary);
  color: #ffffff;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  font-weight: 600;
  border: 2px solid var(--color-primary);
  border-radius: 4px;
  cursor: pointer;
  transition: var(--transition);
  min-height: 44px;
  min-width: 44px;
  font-family: var(--font-sans);
}

button:hover, .btn:hover {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary-light);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

/* Forms */
label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

input, textarea, select {
  width: 100%;
  padding: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  min-height: 44px;
}

input:focus, textarea:focus, select:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 0;
  border-color: var(--color-primary);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

/* Cards */
.card {
  background-color: var(--color-light);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: var(--spacing-lg);
  transition: var(--transition);
}

.card:hover {
  box-shadow: 0 4px 12px rgba(45, 80, 22, 0.1);
  transform: translateY(-4px);
}

/* Grid Helper */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-cols-2 {
  grid-template-columns: repeat(2, 1fr);
}

.grid-cols-3 {
  grid-template-columns: repeat(3, 1fr);
}

/* Utilities */
.section {
  padding: var(--spacing-2xl) 0;
}

.text-center {
  text-align: center;
}

.text-primary {
  color: var(--color-primary);
}

.bg-light {
  background-color: var(--color-light);
}

.bg-primary {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
}

.bg-primary h2, .bg-primary h3 {
  color: var(--color-accent);
}

/* Mobile (max-width: 600px) */
@media (max-width: 600px) {
  :root {
    --spacing-lg: 1.25rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 2.5rem;
  }

  .header .container {
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .header nav {
    gap: var(--spacing-md);
    justify-content: center;
    width: 100%;
  }

  .header nav a {
    font-size: 0.9rem;
  }

  .logo {
    font-size: 1.25rem;
  }

  .grid-cols-2, .grid-cols-3 {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  button, .btn {
    width: 100%;
    text-align: center;
  }

  input, textarea, select {
    font-size: 16px;
  }
}

/* Desktop (min-width: 601px) */
@media (min-width: 601px) {
  .header .container {
    gap: var(--spacing-2xl);
  }

  .grid-cols-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-cols-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.hero {
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.hero h1 {
  color: var(--color-accent);
  margin-bottom: var(--spacing-md);
}

.hero-tagline {
  font-size: 1.25rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-lg);
  font-weight: 500;
}

.btn-light {
  background-color: var(--color-accent);
  color: var(--color-primary);
  border-color: var(--color-accent);
  font-weight: 700;
}

.btn-light:hover {
  background-color: #e8c547;
  border-color: #e8c547;
  color: var(--color-primary);
}

/* About Section */
.about-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.about-card {
  padding: var(--spacing-lg);
  background-color: var(--color-light);
  border-radius: 6px;
  border-left: 4px solid var(--color-primary);
  transition: var(--transition);
}

.about-card:hover {
  box-shadow: 0 4px 12px rgba(45, 80, 22, 0.1);
  transform: translateY(-4px);
}

.about-card h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-md);
}

/* Schedule Section */
.schedule-intro {
  text-align: center;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-2xl);
}

.schedule-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.schedule-card {
  background-color: #ffffff;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: var(--spacing-lg);
  transition: var(--transition);
}

.schedule-card:hover {
  box-shadow: 0 6px 16px rgba(45, 80, 22, 0.12);
  transform: translateY(-6px);
}

.schedule-card h3 {
  color: var(--color-primary);
  border-bottom: 2px solid var(--color-accent);
  padding-bottom: var(--spacing-md);
  margin-bottom: var(--spacing-lg);
}

.class-list {
  list-style: none;
}

.class-list li {
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-text);
}

.class-list li:last-child {
  border-bottom: none;
}

.class-list strong {
  color: var(--color-primary);
  display: block;
}

.instructor {
  font-size: 0.9rem;
  color: var(--color-text-light);
  font-style: italic;
}

/* Testimonials Section */
.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-lg);
}

.testimonial-card {
  background-color: var(--color-light);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: var(--spacing-lg);
  border-top: 3px solid var(--color-accent);
}

.testimonial-card p {
  margin-bottom: var(--spacing-md);
  font-size: 1rem;
  line-height: 1.7;
}

.testimonial-card p:first-child {
  font-style: italic;
  color: var(--color-text);
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-primary);
  margin: 0 !important;
}

/* Sign-up Section */
.signup-intro {
  text-align: center;
  font-size: 1.1rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-2xl);
}

.signup-form {
  max-width: 600px;
  margin: 0 auto;
  background-color: rgba(255, 255, 255, 0.95);
  padding: var(--spacing-2xl);
  border-radius: 8px;
}

.form-group {
  margin-bottom: var(--spacing-lg);
}

.signup-form label {
  color: var(--color-text);
}

.signup-form input,
.signup-form textarea,
.signup-form select {
  border: 2px solid var(--color-border);
}

.signup-form input:focus,
.signup-form textarea:focus,
.signup-form select:focus {
  border-color: var(--color-primary);
}

.btn-submit {
  width: 100%;
  background-color: var(--color-primary);
  color: #ffffff;
  padding: var(--spacing-md) var(--spacing-lg);
  font-size: 1.1rem;
  font-weight: 700;
  border: 2px solid var(--color-primary);
  border-radius: 4px;
  cursor: pointer;
  transition: var(--transition);
  min-height: 48px;
  text-align: center;
}

.btn-submit:hover {
  background-color: var(--color-primary-light);
  border-color: var(--color-primary-light);
}

.btn-submit:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-submit:active {
  transform: scale(0.98);
}

/* Mobile Responsive */
@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-xl) 0;
  }

  .hero-tagline {
    font-size: 1.1rem;
  }

  .about-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .schedule-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .testimonials-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .signup-form {
    padding: var(--spacing-lg);
  }

  .hero h1 {
    font-size: 1.75rem;
  }
}

/* Desktop Responsive */
@media (min-width: 601px) {
  .about-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .schedule-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .testimonials-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

